import { STAGES, toNumber, parseDate, normalizeAccounts, normalizePaperwork, normalizeSignals, extractNoteKinds } from './normalize.js';

// Rules-based analysis. Nothing here is generated by an LLM or invented: every output is a
// deterministic function of the cached MCP responses and carries evidence IDs.
// Evidence IDs are references to real records (PREFIX:<id from data>, or PREFIX:<account>:#<index>
// when the record has no id) plus a `locator` pointing into the stored raw response.

const DAY = 86400000;
const norm = (s) => String(s || '').toLowerCase();
const fmtDays = (d) => (d < 0 ? `${-d} day(s) overdue` : d === 0 ? 'due today' : `in ${d} day(s)`);

const AMOUNT_RE = /(?:[$€£₹]|USD|EUR|GBP|INR)\s?\d[\d,]*(?:\.\d+)?\s?(?:k|m|million|thousand|lakh|cr|crore)?\b|\b\d[\d,]*(?:\.\d+)?\s?(?:k|m|million|thousand|lakh|crore)\b/gi;
export const amountsIn = (text) => [...String(text || '').matchAll(AMOUNT_RE)].map((m) => ({ token: m[0].trim(), value: toNumber(m[0]), index: m.index })).filter((a) => a.value != null);

function snippet(text, index, len = 160) {
  const s = Math.max(0, index - 70);
  return (s > 0 ? '…' : '') + String(text).slice(s, s + len).replace(/\s+/g, ' ').trim() + '…';
}

export function buildModel({ raw, localActions = [], newSignalKeys = [], reviewFlags = {}, now = Date.now() }) {
  const accountsRaw = raw.get_my_accounts?.payload;
  const accounts = accountsRaw ? normalizeAccounts(accountsRaw) : [];
  const paperwork = raw.get_all_paperwork ? normalizePaperwork(raw.get_all_paperwork.payload, accounts) : [];
  const signals = raw.get_signals ? normalizeSignals(raw.get_signals.payload, accounts) : [];
  const schema = raw.get_data_format?.payload ?? null;

  // ---------- Evidence library ----------
  const evidence = [];
  const addEv = (e) => { evidence.push(e); return e.id; };
  const docEvId = (d, i) => `DOC:${d.id ?? '#' + i}`;
  paperwork.forEach((d, i) => { d.evidenceId = docEvId(d, i); });
  const docsFor = (a) => paperwork.filter((d) => d.accountId === a.id || (!d.accountId && norm(d.content).includes(norm(a.name))));

  if (schema != null) addEv({ id: 'SCHEMA:get_data_format', type: 'Data schema', accountId: null, description: 'Field definitions returned by get_data_format', source: 'get_data_format', status: 'Verified', locator: 'get_data_format', tool: 'get_data_format', rawRecord: schema });

  for (const a of accounts) {
    a.evidenceId = addEv({ id: `ACCT:${a.id}`, type: 'Account sheet', accountId: a.id, description: `Account record for ${a.name}${a.overview ? ': ' + a.overview.slice(0, 200) : ''}`, source: 'get_my_accounts', status: 'Unverified', locator: a.locator, tool: 'get_my_accounts', rawRecord: Object.fromEntries(Object.entries(a.raw).filter(([k]) => !/^(deals|opportunities|pipeline|people|stakeholders|contacts|people_met|persons)$/i.test(k))) });
    const docs = docsFor(a);

    a.people.forEach((p, j) => {
      p.evidenceId = addEv({ id: `PERSON:${a.id}:${p.id ?? p.key.split(':')[1]}`, type: 'Stakeholder', accountId: a.id, description: `${p.name}${p.title ? ', ' + p.title : ''}${p.relationshipRaw ? ' — ' + p.relationshipRaw : ''}${p.quote ? ' — "' + p.quote.slice(0, 140) + '"' : ''}`, source: 'get_my_accounts', status: p.quote || p.sourceRef ? 'Told' : 'Unverified', locator: p.locator, tool: 'get_my_accounts', rawRecord: p.raw });
      p.status = p.quote || p.sourceRef ? 'Told' : 'Unverified';
    });

    a.deals.forEach((d, j) => {
      d.evidenceId = `DEAL:${a.id}:${d.id ?? '#' + j}`;
      const support = []; // {evidenceId, via, snippet}
      let status = d.value == null ? 'Unknown' : 'Unverified';
      let basis = d.value == null ? 'No value in account data' : 'Value appears only on the account sheet';
      const person = d.sourceRef && a.people.find((p) => norm(p.name) === norm(d.sourceRef));
      const refDoc = d.sourceRef && docs.find((x) => norm(x.id) === norm(d.sourceRef) || norm(x.title) === norm(d.sourceRef));
      if (d.value != null) {
        if (refDoc) { status = 'Verified'; basis = `Cited source matches ${refDoc.evidenceId}`; support.push({ evidenceId: refDoc.evidenceId, via: 'cited source' }); }
        for (const doc of docs) {
          const hit = amountsIn(doc.content).find((m) => m.value === d.value);
          if (hit && !support.some((s) => s.evidenceId === doc.evidenceId)) {
            support.push({ evidenceId: doc.evidenceId, via: 'amount found in document', snippet: snippet(doc.content, hit.index) });
            if (status !== 'Verified') { status = 'Verified'; basis = `Same amount (${hit.token}) found in ${doc.evidenceId}`; }
          }
        }
        if (status !== 'Verified' && (person || d.sourceRef)) { status = 'Told'; basis = person ? `Stated by ${person.name} (${person.evidenceId})` : `Source cited as "${d.sourceRef}" (not matched to a paperwork record)`; if (person) support.push({ evidenceId: person.evidenceId, via: 'stated by person' }); }
        if (d.verifiedFlag === true && status !== 'Verified') { status = 'Verified'; basis = 'Marked verified in account data'; }
      }
      // Conflict: a document that mentions this deal quotes different amounts and none equals the sheet value
      let conflict = null;
      if (d.value != null) {
        for (const doc of docs) {
          const mentions = norm(doc.content).includes(norm(d.title)) || (d.id && norm(doc.content).includes(norm(d.id)));
          if (!mentions) continue;
          const all = amountsIn(doc.content);
          if (all.length && !all.some((m) => m.value === d.value)) conflict = { evidenceId: doc.evidenceId, amounts: [...new Set(all.map((m) => m.token))].slice(0, 5) };
        }
      }
      d.valueStatus = status; d.valueBasis = basis; d.support = support; d.conflict = conflict;
      addEv({ id: d.evidenceId, type: 'Deal', accountId: a.id, description: `${d.title}${d.value != null ? ' — ' + (d.currency || '') + d.value.toLocaleString('en-US') : ' — value unknown'}${d.stageRaw ? ' [' + d.stageRaw + ']' : ''}`, source: 'get_my_accounts', status, locator: d.locator, tool: 'get_my_accounts', basis, rawRecord: d.raw, support: support.map((x) => ({ ...x })) });
    });
  }
  paperwork.forEach((d, i) => addEv({ id: d.evidenceId, type: `Paperwork${d.type ? ' · ' + d.type : ''}`, accountId: d.accountId, description: d.title + (d.content ? ' — ' + d.content.replace(/\s+/g, ' ').slice(0, 220) : ''), source: d.author ? `get_all_paperwork (${d.author})` : 'get_all_paperwork', status: 'Verified', locator: d.locator, tool: 'get_all_paperwork', date: d.date, rawRecord: d.raw }));
  signals.forEach((s, i) => { s.evidenceId = `SIG:${s.id ?? '#' + i}`; addEv({ id: s.evidenceId, type: `Signal${s.type ? ' · ' + s.type : ''}`, accountId: s.accountId, description: s.description || '(no description)', source: 'get_signals', status: 'Told', locator: s.locator, tool: 'get_signals', date: s.timestamp, rawRecord: s.raw }); });

  // ---------- Per-account analysis ----------
  const days = (dateStr) => { const d = parseDate(dateStr); return d ? Math.ceil((d.getTime() - now) / DAY) : null; };
  const perAccount = accounts.map((a) => analyseAccount(a, { docs: docsFor(a), signals: signals.filter((s) => s.accountId === a.id), newSignalKeys, localActions: localActions.filter((x) => x.account === a.id), days, now, reviewFlag: reviewFlags[a.id] }));

  // ---------- Executive overview ----------
  const allDeals = accounts.flatMap((a) => a.deals);
  const sumBy = (status) => allDeals.filter((d) => d.valueStatus === status && d.value != null).reduce((s, d) => s + d.value, 0);
  const stageCounts = Object.fromEntries([...STAGES, 'Unknown'].map((s) => [s, allDeals.filter((d) => (d.stage || 'Unknown') === s).length]));
  const upcoming = allDeals.map((d) => ({ d, n: days(d.deadline) })).filter((x) => x.n != null && x.n >= 0 && x.n <= 30).sort((x, y) => x.n - y.n)
    .map(({ d, n }) => ({ account: d.accountId, deal: d.title, deadline: d.deadline, inDays: n, evidenceId: d.evidenceId }));
  const risks = perAccount.flatMap((p) => p.q4.items);
  const overview = {
    totalAccounts: accounts.length,
    totalDeals: allDeals.length,
    verifiedValue: sumBy('Verified'), toldValue: sumBy('Told'), unverifiedValue: sumBy('Unverified'),
    unknownValueDeals: allDeals.filter((d) => d.value == null).length,
    stageCounts, blockedDeals: allDeals.filter((d) => d.blocked && d.stage !== 'Agreed').length,
    criticalRisks: risks.filter((r) => r.severity === 'critical').length,
    warningRisks: risks.filter((r) => r.severity === 'warning').length,
    renewalRisks: risks.filter((r) => r.category === 'Renewal risk'),
    upcomingDeadlines: upcoming,
    healthByAccount: perAccount.map((p) => ({ accountId: p.accountId, name: p.name, health: p.health })),
    valueByAccount: perAccount.map((p) => ({ accountId: p.accountId, name: p.name, total: p.q1.totals.all, verified: p.q1.totals.Verified })),
    criteria: {
      fiveQuestions: accounts.length > 0,
      tracedNumbers: allDeals.filter((d) => d.value != null).length ? { traced: allDeals.filter((d) => d.value != null && d.support.length).length, total: allDeals.filter((d) => d.value != null).length } : null,
      moves: perAccount.map((p) => ({ accountId: p.accountId, count: p.q3.length })),
      unknowns: perAccount.map((p) => ({ accountId: p.accountId, count: p.q5.length })),
      signals: signals.length, newSignals: signals.filter((s) => newSignalKeys.includes(s.key)).length,
    },
  };

  return {
    accounts: accounts.map(({ raw: _r, ...rest }) => ({ ...rest, people: rest.people.map(({ raw, ...p }) => p), deals: rest.deals.map(({ raw, ...d }) => d) })),
    paperwork: paperwork.map(({ raw, ...d }) => d),
    signals: signals.map(({ raw, ...s }) => ({ ...s, isNew: newSignalKeys.includes(s.key) })),
    schema, noteKinds: extractNoteKinds(schema),
    evidence, analysis: perAccount, overview,
  };
}

function analyseAccount(a, ctx) {
  const { docs, signals, localActions, days, now, newSignalKeys } = ctx;
  const deals = a.deals;
  const people = a.people;
  const dmNames = new Set(deals.map((d) => norm(d.decisionMaker)).filter(Boolean));
  const boNames = new Set(deals.map((d) => norm(d.budgetOwner)).filter(Boolean));
  const roleOf = (p) => p.role || (dmNames.has(norm(p.name)) ? 'decision_maker' : boNames.has(norm(p.name)) ? 'economic_buyer' : null);
  const personEv = (name) => people.find((p) => norm(p.name) === norm(name))?.evidenceId;

  // ----- Q1: What is the book worth? -----
  const q1deals = deals.map((d) => ({
    key: d.key, title: d.title, value: d.value, currency: d.currency, stage: d.stage || 'Unknown', status: d.valueStatus,
    basis: d.valueBasis, evidenceIds: [d.evidenceId, ...d.support.map((s) => s.evidenceId)], support: d.support,
    source: d.support[0]?.evidenceId || (d.sourceRef ? `Cited: ${d.sourceRef}` : 'Account sheet only'),
    conflict: d.conflict,
  }));
  const totals = { all: 0, Verified: 0, Told: 0, Unverified: 0, unknownCount: 0 };
  for (const d of q1deals) { if (d.value == null) { totals.unknownCount++; continue; } totals.all += d.value; totals[d.status] = (totals[d.status] || 0) + d.value; }
  const q1 = { deals: q1deals, totals, unsupported: q1deals.filter((d) => d.status === 'Unverified' || d.status === 'Unknown'), conflicts: q1deals.filter((d) => d.conflict) };

  // ----- Q2: Who holds the power? -----
  const group = (role) => people.filter((p) => roleOf(p) === role);
  const named = (names, role) => [...names].filter((n) => !people.some((p) => norm(p.name) === n)).map((n) => ({ name: deals.map((d) => d.decisionMaker || d.budgetOwner).find((x) => norm(x) === n) || n, mentionedAs: role, metStatus: 'Named on a deal but not found in the people list' }));
  const q2 = {
    decisionMakers: [...group('decision_maker'), ...named(dmNames, 'decision maker')],
    budgetOwners: [...group('economic_buyer'), ...named(boNames, 'budget owner')],
    users: group('user'), champions: group('champion'), blockers: group('blocker'), influencers: group('influencer'),
    roleUnknown: people.filter((p) => !roleOf(p) && p.met !== false),
    notMet: people.filter((p) => p.met === false),
    standing: people.map((p) => ({ name: p.name, title: p.title, relationship: p.relationship || 'Unknown', evidenceId: p.evidenceId })),
    edges: people.map((p) => ({ name: p.name, role: roleOf(p), relationship: p.relationship || 'Unknown' })),
  };

  // ----- Q4: What is about to go wrong? -----
  const items = [];
  const risk = (r) => items.push({ accountId: a.id, accountName: a.name, ...r });
  for (const d of deals) {
    const n = days(d.deadline);
    const closed = d.stage === 'Agreed';
    if (n != null && !closed) {
      if (n < 0) risk({ severity: 'critical', category: 'Deadline at risk', title: `${d.title}: deadline passed`, detail: `Deadline ${d.deadline} was ${fmtDays(n)} and the deal is ${d.stage || 'of unknown stage'}.`, evidenceIds: [d.evidenceId], dealKey: d.key });
      else if (n <= 7) risk({ severity: 'critical', category: 'Deadline at risk', title: `${d.title}: deadline ${fmtDays(n)}`, detail: `Deadline ${d.deadline}; stage is ${d.stage || 'Unknown'}${d.blocked ? ' and a blocker is unresolved' : ''}.`, evidenceIds: [d.evidenceId], dealKey: d.key });
      else if (n <= 21) risk({ severity: 'warning', category: 'Upcoming commitment', title: `${d.title}: deadline ${fmtDays(n)}`, detail: `Deadline ${d.deadline}; stage is ${d.stage || 'Unknown'}.`, evidenceIds: [d.evidenceId], dealKey: d.key });
    } else if (!closed && n == null) {
      risk({ severity: 'warning', category: 'Deadline at risk', title: `${d.title}: no confirmed deadline`, detail: d.deadline ? `Deadline "${d.deadline}" could not be read as a date.` : 'No deadline in the account data, so urgency cannot be assessed.', evidenceIds: [d.evidenceId], dealKey: d.key });
    }
    if (d.blocked && !closed) {
      const urgent = n != null && n <= 14;
      risk({ severity: urgent ? 'critical' : 'warning', category: d.blocker ? 'Unresolved blocker' : 'Blocked deal', title: `${d.title}: ${d.blocker ? 'blocker open' : 'flagged as blocked'}`, detail: `${(d.blocker || 'Deal is flagged blocked without a stated reason.').replace(/[.\s]*$/, '.')}${urgent ? ` Deadline is ${fmtDays(n)}.` : ''}`, evidenceIds: [d.evidenceId], dealKey: d.key });
    }
    if (d.stage && ['Blocker Cleared', 'Agreed'].includes(d.stage) && d.blocker) risk({ severity: 'warning', category: 'Contradiction', title: `${d.title}: stage "${d.stage}" but a blocker is still listed`, detail: `Blocker text: ${d.blocker}. Confirm which is current.`, evidenceIds: [d.evidenceId], dealKey: d.key });
    if (d.type && /renew/i.test(d.type) && !closed) {
      const sev = n != null && n <= 30 ? (n <= 14 || d.blocked ? 'critical' : 'warning') : 'warning';
      risk({ severity: sev, category: 'Renewal risk', title: `${d.title}: renewal not yet agreed`, detail: `Renewal stage ${d.stage || 'Unknown'}${n != null ? `, deadline ${fmtDays(n)}` : ', no deadline on record'}${d.blocked ? `, blocker: ${d.blocker || 'flagged blocked'}` : ''}.`, evidenceIds: [d.evidenceId], dealKey: d.key });
    }
    if (d.conflict) risk({ severity: 'warning', category: 'Contradiction', title: `${d.title}: value differs between sheet and paperwork`, detail: `Account sheet says ${d.value?.toLocaleString('en-US')}; ${d.conflict.evidenceId} mentions ${d.conflict.amounts.join(', ')}.`, evidenceIds: [d.evidenceId, d.conflict.evidenceId], dealKey: d.key });
  }
  for (const p of people) {
    const isDM = roleOf(p) === 'decision_maker', isBO = roleOf(p) === 'economic_buyer';
    if (p.relationship === 'Guarded') risk({ severity: isDM || isBO || roleOf(p) === 'blocker' ? 'critical' : 'warning', category: isDM ? 'Disengaged decision maker' : 'Cold stakeholder', title: `${p.name} is Guarded${isDM ? ' (decision maker)' : isBO ? ' (budget owner)' : ''}`, detail: `Relationship recorded as "${p.relationshipRaw}".${p.waitingFor ? ` Waiting for: ${p.waitingFor}.` : ''}`, evidenceIds: [p.evidenceId] });
    else if (p.relationship === 'Neutral' && (isDM || isBO)) risk({ severity: 'warning', category: 'Cold stakeholder', title: `${p.name} is only Neutral toward us (${isDM ? 'decision maker' : 'budget owner'})`, detail: 'A decision maker who is not Warm/Ally is a risk to closing.', evidenceIds: [p.evidenceId] });
    else if (p.relationship === 'Warm' || p.relationship === 'Ally') risk({ severity: 'healthy', category: 'Healthy', title: `${p.name} is ${p.relationship}`, detail: `Relationship recorded as "${p.relationshipRaw}".`, evidenceIds: [p.evidenceId] });
  }
  for (const r of a.risks) risk({ severity: 'warning', category: 'Renewal risk', title: 'Risk recorded on account sheet', detail: r, evidenceIds: [a.evidenceId] });
  for (const s of signals) if (/delay|fail|miss|slip|late|postpone|cancel|escalat|churn|competitor/i.test(s.description || '')) risk({ severity: 'warning', category: 'Failed or delayed action', title: `Signal: ${s.type || 'event'}`, detail: s.description, evidenceIds: [s.evidenceId] });
  for (const t of localActions) if (t.status !== 'done' && t.due && days(t.due) != null && days(t.due) < 0) risk({ severity: 'warning', category: 'Failed or delayed action', title: `Local CRM task overdue: ${t.title}`, detail: `Local planning task (not a game action) was due ${t.due}.`, evidenceIds: [] });
  for (const d of deals) if (d.stage === 'Agreed') risk({ severity: 'healthy', category: 'Healthy', title: `${d.title}: Agreed`, detail: 'Stage is Agreed in account data.', evidenceIds: [d.evidenceId], dealKey: d.key });

  const order = { critical: 0, warning: 1, healthy: 2 };
  items.sort((x, y) => order[x.severity] - order[y.severity]);
  const nCrit = items.filter((i) => i.severity === 'critical').length, nWarn = items.filter((i) => i.severity === 'warning').length;
  const health = !deals.length && !people.length ? 'Unknown' : nCrit ? 'Critical' : nWarn ? 'Warning' : items.some((i) => i.severity === 'healthy') ? 'Healthy' : 'Unknown';
  const q4 = { items, counts: { critical: nCrit, warning: nWarn, healthy: items.filter((i) => i.severity === 'healthy').length } };

  // ----- Q3: What do you do first? -----
  const maxValue = Math.max(0, ...deals.map((d) => d.value || 0));
  const cand = [];
  const stageIdx = (d) => STAGES.indexOf(d.stage);
  for (const d of deals) {
    if (d.stage === 'Agreed') continue;
    const n = days(d.deadline);
    const parts = [];
    let score = 0;
    if (d.value != null && maxValue) { const v = Math.round((d.value / maxValue) * 40); score += v; parts.push(`value ${d.currency || ''}${d.value.toLocaleString('en-US')} (+${v})`); }
    if (n != null) { const u = n < 0 ? 35 : n <= 7 ? 30 : n <= 14 ? 20 : n <= 30 ? 10 : 3; score += u; parts.push(`deadline ${fmtDays(n)} (+${u})`); }
    if (d.blocked) { score += 15; parts.push('open blocker (+15)'); }
    if (d.type && /renew/i.test(d.type)) { score += 10; parts.push('renewal (+10)'); }
    if (d.probability != null) { const pb = Math.round(d.probability <= 1 ? d.probability * 10 : d.probability / 10); score += pb; parts.push(`stated win chance ${d.probability} (+${pb})`); }
    const nextStage = STAGES[Math.min(STAGES.length - 1, Math.max(0, stageIdx(d)) + 1)];
    let action;
    if (d.nextAction) action = d.nextAction;
    else if (d.blocked) action = `Clear the blocker on "${d.title}": ${d.blocker || 'identify and resolve what is blocking it'}`;
    else if (d.stage === 'Identified' || !d.stage) action = `Qualify "${d.title}"${d.requiredEvidence ? ` by gathering: ${d.requiredEvidence}` : ' — confirm need, budget and decision maker'}`;
    else action = `Advance "${d.title}" from ${d.stage}${d.requiredEvidence ? `; required evidence: ${d.requiredEvidence}` : ''}`;
    cand.push({ type: 'deal', dealKey: d.key, dealTitle: d.title, action, score, parts, evidenceIds: [d.evidenceId, ...d.support.map((s) => s.evidenceId)], outcome: `"${d.title}" moves ${d.stage || 'from Unknown'} → ${nextStage}`, deadline: d.deadline, deadlineDays: n, owner: d.owner, chance: d.probability, value: d.value });
    if (d.value != null && d.valueStatus === 'Unverified' && d.value >= maxValue * 0.5) cand.push({ type: 'evidence', dealKey: d.key, dealTitle: d.title, action: `Get documentary proof for the ${d.currency || ''}${d.value.toLocaleString('en-US')} value of "${d.title}" (only on the account sheet)`, score: Math.round(score * 0.6), parts: ['high-value deal with unverified amount'], evidenceIds: [d.evidenceId], outcome: 'Deal value becomes defensible with a source ID', deadline: d.deadline, deadlineDays: n, value: d.value });
  }
  for (const p of people) {
    const role = roleOf(p);
    if (p.met === false && (role === 'decision_maker' || role === 'economic_buyer' || !role)) cand.push({ type: 'meet', dealKey: null, dealTitle: null, action: `Secure a first meeting with ${p.name}${p.title ? ' (' + p.title + ')' : ''}`, score: role ? 28 : 12, parts: [role ? `${role.replace('_', ' ')} not yet met (+28)` : 'stakeholder not yet met (+12)'], evidenceIds: [p.evidenceId], outcome: 'Stakeholder met; role and stance verified', deadlineDays: null });
    if (p.relationship === 'Guarded' && (role === 'decision_maker' || role === 'economic_buyer' || role === 'blocker')) cand.push({ type: 'engage', dealKey: null, dealTitle: null, action: `Re-engage ${p.name}${p.waitingFor ? ' — they are waiting for: ' + p.waitingFor : ''}`, score: 30, parts: ['guarded power holder (+30)'], evidenceIds: [p.evidenceId], outcome: `${p.name} moves from Guarded toward Neutral/Warm`, deadlineDays: null });
  }
  for (const s of signals.filter((x) => newSignalKeys.includes(x.key))) cand.push({ type: 'signal', dealKey: null, dealTitle: s.deal, action: `Respond to new signal: ${(s.description || s.type || 'event').slice(0, 140)}`, score: 25, parts: ['new live signal (+25)'], evidenceIds: [s.evidenceId], outcome: 'Signal triaged; affected insights reviewed', deadlineDays: null });

  cand.sort((x, y) => y.score - x.score);
  const picked = [];
  const perDeal = {};
  for (const c of cand) { // at most 2 moves per deal for a diverse top three
    const k = c.dealKey || c.action;
    if ((perDeal[k] || 0) >= 2) continue;
    perDeal[k] = (perDeal[k] || 0) + 1; picked.push(c);
    if (picked.length === 3) break;
  }
  const q3 = picked.map((c, i) => {
    const target = new Date(now + [1, 3, 5][i] * DAY);
    let due = c.deadline && c.deadlineDays != null ? c.deadline : null, basis = 'customer deadline';
    if (!due || (c.deadlineDays != null && c.deadlineDays < 0)) {
      due = target.toISOString().slice(0, 10); basis = 'proposed internal target (no usable customer deadline in data)';
    } else if (c.deadlineDays != null && c.deadlineDays > 7) {
      due = target.toISOString().slice(0, 10); basis = `proposed internal target ahead of customer deadline ${c.deadline}`;
    }
    return {
      priority: i + 1, action: c.action, owner: c.owner || 'Account CSM (default — reassign as needed)', ownerFromData: Boolean(c.owner),
      due, dueBasis: basis, customerDeadline: c.deadline || null, accountId: a.id, accountName: a.name, deal: c.dealTitle || 'Not deal-specific',
      evidenceIds: c.evidenceIds, expectedOutcome: c.outcome, reason: c.parts.join('; ') || 'No scoring inputs available in data',
      chanceOfSuccess: c.chance != null ? String(c.chance) : 'Not stated in data', score: c.score, kind: c.type, recommendation: true,
    };
  });

  // ----- Q5: What do you still not know? -----
  const q5 = [];
  const unk = (u) => q5.push({ accountId: a.id, accountName: a.name, ...u });
  if (!q2.decisionMakers.length) unk({ category: 'Missing decision maker', missing: 'No decision maker is identified for this account.', why: 'Without a decision maker we cannot know who signs or what they need.', who: 'Champion or day-to-day contact; paperwork', question: 'Who signs off on this purchase or renewal, and what do they need to see?', evidenceIds: [a.evidenceId] });
  if (!q2.budgetOwners.length) unk({ category: 'Unknown budget approval', missing: 'No budget owner / economic buyer is identified.', why: 'Deals stall when the payer is unknown.', who: 'Decision maker; finance or procurement contact', question: 'Who owns the budget and has it been approved?', evidenceIds: [a.evidenceId] });
  for (const d of deals) {
    if (d.value == null) unk({ category: 'Unverified deal value', missing: `No value recorded for "${d.title}".`, why: 'The book cannot be totalled defensibly.', who: d.decisionMaker || d.budgetOwner || 'Account owner', question: `What is the agreed or expected value of "${d.title}", and where is it written down?`, evidenceIds: [d.evidenceId], dealKey: d.key });
    else if (d.valueStatus === 'Unverified') unk({ category: 'Unverified deal value', missing: `Value of "${d.title}" (${d.value.toLocaleString('en-US')}) appears only on the account sheet.`, why: 'Unsupported amounts must not be presented as facts.', who: d.budgetOwner || d.decisionMaker || 'Customer finance contact', question: `Can you confirm ${d.value.toLocaleString('en-US')} for "${d.title}" in writing?`, evidenceIds: [d.evidenceId], dealKey: d.key });
    if (!d.deadline) unk({ category: 'Unconfirmed deadline', missing: `No deadline for "${d.title}".`, why: 'Urgency and ranking depend on dates.', who: d.decisionMaker || 'Customer sponsor', question: `By when must "${d.title}" be decided?`, evidenceIds: [d.evidenceId], dealKey: d.key });
    else if (days(d.deadline) == null) unk({ category: 'Unconfirmed deadline', missing: `Deadline "${d.deadline}" for "${d.title}" is not a parseable date.`, why: 'Cannot compute urgency.', who: d.decisionMaker || 'Customer sponsor', question: 'What is the exact calendar date?', evidenceIds: [d.evidenceId], dealKey: d.key });
    if (d.requiredEvidence == null && d.stage !== 'Agreed') unk({ category: 'Unknown requirement', missing: `Evidence required to move "${d.title}" forward is not stated.`, why: 'We do not know what proof clears the next stage.', who: d.decisionMaker || 'Champion', question: `What must we show for "${d.title}" to move past ${d.stage || 'its current stage'}?`, evidenceIds: [d.evidenceId], dealKey: d.key });
    if (d.type && /renew/i.test(d.type) && !a.renewalDate && !d.deadline) unk({ category: 'Unknown renewal requirements', missing: `Renewal terms/date for "${d.title}" unknown.`, why: 'Renewal risk cannot be assessed.', who: 'Customer admin / contract owner', question: 'What are the renewal date and conditions?', evidenceIds: [d.evidenceId], dealKey: d.key });
  }
  for (const p of q2.notMet) unk({ category: 'Missing stakeholder relationship', missing: `${p.name}${p.title ? ' (' + p.title + ')' : ''} has not been met.`, why: 'Their stance and influence are unverified.', who: 'Champion introduction', question: `Can you introduce us to ${p.name}? What do they care about?`, evidenceIds: [p.evidenceId] });
  for (const p of people) if (p.met !== false && !p.relationship) unk({ category: 'Missing stakeholder relationship', missing: `Relationship status for ${p.name} is not recorded.`, why: 'Cannot tell whether they are an ally or blocker.', who: 'Whoever last spoke to them', question: `Where does ${p.name} stand with us?`, evidenceIds: [p.evidenceId] });
  const techDocs = docs.filter((x) => /technical|integration|architecture|spec|security|api|deploy|requirement/i.test(`${x.title} ${x.type || ''}`));
  if (!techDocs.length) unk({ category: 'Missing technical documentation', missing: 'No technical document (spec, integration, security) found in the retrieved paperwork for this account.', why: 'Technical blockers cannot be verified from evidence.', who: 'Customer IT / product users', question: 'Is there a technical requirements or security document we should review?', evidenceIds: [a.evidenceId] });
  if (!docs.length) unk({ category: 'No supporting paperwork', missing: 'No paperwork matched this account.', why: 'Every number then rests on the account sheet or on what people said.', who: 'Account owner', question: 'Which contracts, quotes or emails support this account?', evidenceIds: [a.evidenceId] });

  // If fewer than three deal/people moves exist, fill with moves that close the highest-value unknowns.
  const fillOrder = ['Missing decision maker', 'Unknown budget approval', 'Unverified deal value', 'Missing stakeholder relationship', 'Unconfirmed deadline', 'Unknown requirement', 'Unknown renewal requirements', 'Missing technical documentation', 'No supporting paperwork'];
  const spare = [...q5].sort((x, y) => fillOrder.indexOf(x.category) - fillOrder.indexOf(y.category));
  for (const u of spare) {
    if (q3.length >= 3) break;
    if (q3.some((m) => m.action.includes(u.question))) continue;
    const i = q3.length, target = new Date(now + [1, 3, 5][i] * DAY);
    q3.push({ priority: i + 1, action: `Close an unknown: ask "${u.question}"`, owner: 'Account CSM (default — reassign as needed)', ownerFromData: false, due: target.toISOString().slice(0, 10), dueBasis: 'proposed internal target (no customer deadline applies)', customerDeadline: null, accountId: a.id, accountName: a.name, deal: u.dealKey ? (deals.find((d) => d.key === u.dealKey)?.title || 'Not deal-specific') : 'Not deal-specific', evidenceIds: u.evidenceIds, expectedOutcome: `Unknown resolved: ${u.missing}`, reason: `No higher-scoring deal move available; ${u.why}`, chanceOfSuccess: 'Not stated in data', score: 0, kind: 'unknown', recommendation: true });
  }

  const reviewNote = ctx.reviewFlag ? { since: ctx.reviewFlag.since, reason: ctx.reviewFlag.reason } : null;
  return { accountId: a.id, name: a.name, health, q1, q2, q3, q4, q5, reviewNote, summary: summarise(a, q1, q2, q3, q4, q5) };
}

function summarise(a, q1, q2, q3, q4, q5) {
  const money = (n) => (n ? n.toLocaleString('en-US') : '0');
  const lines = [];
  lines.push(`${a.name} has ${a.deals.length} deal(s) worth ${money(q1.totals.all)} in total; ${money(q1.totals.Verified)} is verified by documents and ${money(q1.totals.Told + q1.totals.Unverified)} is told/unverified${q1.totals.unknownCount ? `, plus ${q1.totals.unknownCount} deal(s) with no value` : ''}.`);
  lines.push(`${q4.counts.critical} critical and ${q4.counts.warning} warning risks found; ${q5.length} open unknown(s).`);
  if (q3[0]) lines.push(`First move: ${q3[0].action} (owner ${q3[0].owner}, due ${q3[0].due}).`);
  if (q2.notMet.length) lines.push(`${q2.notMet.length} stakeholder(s) not yet met.`);
  return { lines, label: 'Rules-based recommendation, not a verified fact' };
}
